with latest as (select *, row_number() over (partition by order_id order by paid_at desc nulls last, id) as rn from payments qualify rn = 1) select case when amount >= 1560 then 'LARGE' else 'SMALL' end as amount_tier, status, sort_array(collect_set(status)) as status_list, count_if(status = 'FAILED') as failed_events, round(sum(amount) / nullif(count(case when method = 'promptpay' then 1 end), 0), 2) as amount_per_promptpay, grouping(case when amount >= 1560 then 'LARGE' else 'SMALL' end) as grouping_id from latest group by cube (case when amount >= 1560 then 'LARGE' else 'SMALL' end, status) having failed_events > 1;
